/* ───────────── Googie Orbit Diner ───────────── */
interface GoogieInk { bg: string; mid: string; raised: string; cherry: string; teal: string; butter: string; cream: string; pink: string; green: string; chrome: string }
const googie = world<GoogieInk>('googie-orbit-diner', 'Googie Orbit Diner', 'Boomerang formica, checkerboard floors, starburst clocks, cherry vinyl booths, and milkshakes served in zero gravity.', ['retro-future','googie','diner','atomic','50s','space','cherry','turquoise'],
  { skin: skin('#0a0d1f','#151a36','#22294f','#fff6ea','#b8b6c9','#ff3d5a','#3fd1c7'), ink: { bg: '#0a0d1f', mid: '#151a36', raised: '#22294f', cherry: '#ff3d5a', teal: '#3fd1c7', butter: '#ffd166', cream: '#fff6ea', pink: '#ff9db0', green: '#6fd34a', chrome: '#c9d2e0' } },
  { skin: skin('#f4f1e6','#fffdf6','#dff2ef','#1a1f3d','#565a78','#d11f3c','#1a8f87'), ink: { bg: '#f4f1e6', mid: '#dff2ef', raised: '#bfe8e3', cherry: '#e02848', teal: '#1aa89e', butter: '#f5b700', cream: '#fffdf6', pink: '#ff8aa2', green: '#3fa82a', chrome: '#8a93a8' } },
  (k, mode) => {
    const formica = svg(`<g fill="none" stroke-width="5" stroke-linecap="round" opacity=".34"><path d="M14 30q16-18 34 4" stroke="${k.teal}"/><path d="M70 86q18-20 36 2" stroke="${k.cherry}"/><path d="M76 18q10 16-6 30" stroke="${k.butter}"/><path d="M20 90q14 12 30-2" stroke="${k.teal}"/></g><g fill="${mode === 'dark' ? k.cream : k.chrome}" opacity=".5"><circle cx="56" cy="56" r="2"/><circle cx="104" cy="40" r="1.5"/><circle cx="36" cy="108" r="1.5"/></g>`, '0 0 120 120')
    const starburst = (() => {
      let rays = ''
      for (let i = 0; i < 12; i++) {
        const t = (i * Math.PI) / 6, l = i % 2 ? 44 : 64
        const x1 = (80 + 30 * Math.cos(t)).toFixed(1), y1 = (120 + 30 * Math.sin(t)).toFixed(1), x2 = (80 + l * Math.cos(t)).toFixed(1), y2 = (120 + l * Math.sin(t)).toFixed(1)
        rays += `<path d="M${x1} ${y1}L${x2} ${y2}"/><circle cx="${x2}" cy="${y2}" r="${i % 2 ? 2.5 : 4}" fill="${i % 2 ? k.teal : k.cherry}" stroke="none"/>`
      }
      return svg(`<g stroke="${k.butter}" stroke-width="3" stroke-linecap="round">${rays}</g><circle cx="80" cy="120" r="26" fill="${mode === 'dark' ? k.mid : k.cream}" stroke="${k.teal}" stroke-width="3"/>`)
    })()
    const milkshake = svg(`<path d="M52 90h56l-10 110H62z" fill="${a(k.cream, .13)}" stroke="${mode === 'dark' ? k.cream : k.chrome}" stroke-width="2"/><path d="M55 110h50l-8 88H63z" fill="${k.pink}"/><path d="M96 92l20-62" stroke="${k.teal}" stroke-width="7" stroke-linecap="round"/><path d="M48 96c0-14 12-14 16-22 6 8 14-6 22 2 8-6 22 4 18 20z" fill="${k.cream}" stroke="${mode === 'dark' ? 'none' : k.chrome}"/><circle cx="80" cy="66" r="9" fill="${k.cherry}"/><path d="M82 58q6-14 16-18" stroke="${k.green}" fill="none" stroke-width="2"/><path d="M66 200h28l6 18H60z" fill="${mode === 'dark' ? k.cream : k.chrome}"/><g fill="${k.pink}"><circle cx="36" cy="70" r="4"/><circle cx="124" cy="130" r="3"/><circle cx="30" cy="150" r="2.5"/></g>`)
    const spark = (x: number, y: number, r: number, c: string) => `<g stroke="${c}" stroke-width="3" stroke-linecap="round">${[0, 45, 90, 135].map((d) => `<path d="M${x - r * Math.cos((d * Math.PI) / 180)} ${y - r * Math.sin((d * Math.PI) / 180)}L${x + r * Math.cos((d * Math.PI) / 180)} ${y + r * Math.sin((d * Math.PI) / 180)}"/>`).join('')}</g><circle cx="${x}" cy="${y}" r="${r / 4}" fill="${c}"/>`
    const diner = `${spark(160, 60, 24, k.butter)}${spark(520, 40, 16, k.teal)}${spark(1450, 70, 20, k.cherry)}${spark(1040, 30, 14, k.butter)}<g transform="translate(1250 90) rotate(-10)"><ellipse rx="90" ry="20" fill="${k.chrome}"/><path d="M-44 -8a44 30 0 0 1 88 0z" fill="${a(k.teal, .7)}"/>${[-60, -20, 20, 60].map((x) => `<circle cx="${x}" cy="4" r="5" fill="${k.butter}"/>`).join('')}</g><path d="M0 380h1600v20H0z" fill="${k.raised}"/>${loop(40, 40, (x, i) => `<rect x="${x}" y="380" width="20" height="10" fill="${i % 2 ? k.cream : k.cherry}"/><rect x="${x + 20}" y="390" width="20" height="10" fill="${i % 2 ? k.cream : k.cherry}"/>`)}<path d="M420 380V230h760v150z" fill="${a(k.mid, .95)}" stroke="${k.cream}" stroke-width="4"/>${loop(9, 80, (x) => `<rect x="${448 + x}" y="252" width="62" height="92" rx="6" fill="${a(k.butter, mode === 'dark' ? .35 : .3)}" stroke="${k.chrome}" stroke-width="3"/>`)}<path d="M380 240L560 150 800 220 1040 140 1220 240z" fill="${k.teal}" stroke="${k.cream}" stroke-width="5"/><path d="M420 350h760" stroke="${k.cherry}" stroke-width="14"/><path d="M300 380V60" stroke="${k.chrome}" stroke-width="10"/><path d="M300 60l-60 60h120z" fill="${k.cherry}"/><rect x="236" y="130" width="128" height="110" rx="20" fill="${k.cherry}" stroke="${k.cream}" stroke-width="5"/><text x="300" y="206" text-anchor="middle" font-family="Arial Black,Arial,sans-serif" font-size="54" fill="${k.cream}">EAT</text>${spark(300, 40, 30, k.butter)}`
    return {
      backdrop: `${landmark(diner)},radial-gradient(ellipse at 80% 20%,${a(k.teal, .19)},transparent 38%),radial-gradient(ellipse at 10% 90%,${a(k.cherry, .13)},transparent 40%),linear-gradient(170deg,var(--venus-raised),var(--venus-bg) 70%)`,
      scene: `${formica},radial-gradient(circle,${a(mode === 'dark' ? k.cream : k.teal, .53)} 0 1px,transparent 1.6px)`, sceneSize: '120px 120px,31px 37px',
      ornament: `repeating-radial-gradient(ellipse at 50% 50%,transparent 0 80px,${a(k.teal, .14)} 81px 83px,transparent 84px 160px),radial-gradient(circle,${a(k.butter, .53)} 0 1.5px,transparent 2.5px),radial-gradient(circle,${a(k.cherry, .4)} 0 1px,transparent 2px)`, ornamentSize: 'auto,53px 61px,37px 29px',
      paper: `radial-gradient(ellipse at 50% 0,${a(k.butter, .06)},transparent 60%)`, line: `linear-gradient(${k.cherry},${k.butter} 35%,${k.teal} 70%,${k.cherry})`, lineSpeed: '3.2s',
      panelLayout: 'fixed',
      panelLeft: `${scenery(starburst)},radial-gradient(ellipse at 50% 50%,${a(k.teal, .2)},transparent 60%),linear-gradient(${k.raised},${mode === 'dark' ? k.bg : k.mid})`,
      panelRight: `radial-gradient(circle,${a(mode === 'dark' ? k.cream : k.teal, .6)} 0 1px,transparent 1.6px) 0 0/23px 29px,linear-gradient(${k.mid},${k.raised} 64%,transparent 64%),conic-gradient(${k.cream} 25%,${k.cherry} 0 50%,${k.cream} 0 75%,${k.cherry} 0) 0 0/22px 22px`,
      panelDetail: sheen, panelGlyphs: ['✷', '✦'],
      panelInteriors: { left: { fontSize: 'clamp(26px,3.4vw,40px)', color: k.butter }, right: { object: `center/contain no-repeat ${milkshake}`, inset: '4% 10% 24%', animation: `venus-play-googie-float 6s ${ease} infinite` } },
      portraitRadius: '46% 12% 46% 12%', plaque: k.cherry, plaqueText: '#fff6ea', plaqueBorder: k.cream, plaqueShadow: `0 0 0 3px ${k.cream},0 0 0 7px ${k.teal},0 0 24px ${a(k.cherry, .67)}`, plaqueInset: studs(`${k.butter} 0 3px,transparent 4px`, `${k.butter} 0 3px,transparent 4px`, 16), plaqueRadius: '40px 12px 40px 12px',
      headingFont: '"Righteous","Futura","Trebuchet MS",sans-serif', bodyFont: '"Outfit","Avenir Next","Segoe UI",system-ui,sans-serif', monoFont: mono,
      ...motion('googie-orbit-diner', {
        scene: [28, ease, drift],
        world: [20, 'linear', 'from{background-position:0 0,0 0,0 0,0 0}to{background-position:0 0,-106px 122px,74px -58px,0 0}'],
        inner: [12, ease, '0%{transform:rotate(0)}8%,25%{transform:rotate(90deg)}33%,50%{transform:rotate(180deg)}58%,75%{transform:rotate(270deg)}83%,100%{transform:rotate(360deg)}'],
        overlay: [4, 'linear', '0%,100%{filter:opacity(.8)}5%{filter:opacity(.3)}6%{filter:opacity(1)}50%{filter:opacity(.7)}52%{filter:opacity(1)}'],
        extra: '@keyframes venus-play-googie-float{0%,100%{transform:translateY(4%) rotate(-8deg)}50%{transform:translateY(-6%) rotate(10deg)}}',
      }),
    }
  })

